# 1: group callback sets ctx.default_map
@click.group()
@click.pass_context
def g1(ctx):
    ctx.default_map = {"cmd": {"flag": True}}

@g1.command()
@click.option("--flag", is_flag=True)
def cmd(flag):
    click.echo(flag)
show("group callback sets ctx.default_map", g1, ["cmd"])

# 2: nested two levels
@click.group()
def g2():
    pass

@g2.group()
def sub():
    pass

